BEGIN;
DO $test$
DECLARE
 v_actor uuid:='00000000-0000-4000-a000-000000008501';v_user uuid:='00000000-0000-4000-a000-000000008502';
 v_office uuid:='00000000-0000-4000-a000-000000008503';v_other uuid:='00000000-0000-4000-a000-000000008504';
 v_admin uuid:='00000000-0000-4000-a000-000000008505';v_membership uuid;
 v_role uuid;v_publisher uuid;v_kind uuid;v_data jsonb;v_claim jsonb;v_denied boolean;
BEGIN
 ASSERT NOT has_table_privilege('authenticated','public.portal_invitation','select');
 ASSERT NOT has_table_privilege('anon','public.portal_invitation','insert');
 ASSERT NOT has_function_privilege('authenticated','api.claim_portal_reminders(integer)','execute');
 PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
 SELECT id INTO v_role FROM public.ref_actor_role WHERE code='operator';
 SELECT id INTO v_publisher FROM public.ref_org_role WHERE code='publisher';
 SELECT id INTO v_kind FROM public.ref_code_contact_kind WHERE code='email';
 INSERT INTO auth.users(id,email) VALUES(v_user,'portal-invite-8502@example.test'),(v_office,'office-invite-8503@example.test'),(v_admin,'admin-invite-8505@example.test');
 INSERT INTO public.app_user_profile(id,role) VALUES(v_office,'super_admin') ON CONFLICT(id) DO UPDATE SET role='super_admin';
 INSERT INTO public.object(id,object_type,name,status,is_test) VALUES('ORGRUN9999998501','ORG','Office lancement test','published',true),
  ('ORGRUN9999998502','ORG','Office étranger test','published',true),('HOTRUN9999998501','HOT','Fiche lancement test','published',true);
 INSERT INTO public.org_config(org_object_id,is_test_org) VALUES('ORGRUN9999998501',true),('ORGRUN9999998502',true)
 ON CONFLICT(org_object_id) DO UPDATE SET is_test_org=true;
 INSERT INTO public.app_user_profile(id,role) VALUES(v_admin,'tourism_agent') ON CONFLICT(id) DO UPDATE SET role='tourism_agent';
 INSERT INTO public.user_org_membership(user_id,org_object_id,is_active) VALUES(v_admin,'ORGRUN9999998501',true) RETURNING id INTO v_membership;
 INSERT INTO public.user_org_admin_role(membership_id,role_id,is_active) SELECT v_membership,id,true FROM public.ref_org_admin_role WHERE code='org_admin';
 INSERT INTO public.actor(id,display_name,is_test,extra) VALUES(v_actor,'Partenaire lancement test',true,'{"test_corpus":true}'),(v_other,'Autre partenaire lancement',true,'{"test_corpus":true}');
 INSERT INTO public.actor_channel(actor_id,kind_id,value,is_primary) VALUES(v_actor,v_kind,'portal-invite-8502@example.test',true);
 INSERT INTO public.actor_object_role(actor_id,object_id,role_id) VALUES(v_actor,'HOTRUN9999998501',v_role);
 INSERT INTO public.object_org_link(object_id,org_object_id,role_id,is_primary) VALUES('HOTRUN9999998501','ORGRUN9999998501',v_publisher,true);
 INSERT INTO public.app_user_profile(id,role,actor_id) VALUES(v_user,'actor',v_actor) ON CONFLICT(id) DO UPDATE SET role='actor',actor_id=v_actor;
 PERFORM api.record_portal_invitation('ORGRUN9999998501',v_actor,v_user,v_office);
 v_denied:=false;BEGIN PERFORM api.record_portal_invitation('ORGRUN9999998502',v_actor,v_user,v_office);EXCEPTION WHEN insufficient_privilege THEN v_denied:=true;END;ASSERT v_denied,'invitation hors office acceptée';
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',v_user,'role','authenticated')::text,true);
 v_denied:=false;BEGIN PERFORM api.get_portal_launch('ORGRUN9999998501');EXCEPTION WHEN insufficient_privilege THEN v_denied:=true;END;ASSERT v_denied,'partenaire lit la console';
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',v_office,'role','authenticated','app_metadata',jsonb_build_object('sandbox_discovery',true))::text,true);
 v_data:=api.get_portal_launch('ORGRUN9999998501');
 ASSERT (v_data#>>'{stats,reachable}')::integer=1 AND (v_data#>>'{stats,invited}')::integer=1;
 ASSERT (v_data#>>'{stats,activated}')::integer=0 AND (v_data#>>'{stats,submitted}')::integer=0;
 ASSERT api.get_portal_launch('ORGRUN9999998502')#>>'{stats,reachable}'='0','fuite entre offices';
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',v_admin,'role','authenticated')::text,true);
 ASSERT api.get_portal_launch('ORGRUN9999998501')#>>'{stats,reachable}'='1','administrateur de cet office refusé';
 ASSERT api.get_portal_launch('ORGRUN9999998501')->>'canInvite'='false','permission invitation donnée par défaut';
 v_denied:=false;BEGIN PERFORM api.get_portal_launch('ORGRUN9999998502');EXCEPTION WHEN insufficient_privilege THEN v_denied:=true;END;ASSERT v_denied,'administrateur lit un autre office';
 PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
 UPDATE public.portal_invitation SET reminder_due_at=now()-interval '1 day' WHERE actor_id=v_actor;
 ASSERT api.claim_portal_reminders(20)='[]'::jsonb,'relance sans SMTP réservée';
 INSERT INTO public.org_smtp_settings(org_object_id,host,from_email,is_enabled) VALUES('ORGRUN9999998501','smtp.example.test','office@example.test',true);
 v_claim:=api.claim_portal_reminders(20)->0;ASSERT v_claim IS NOT NULL;
 ASSERT v_claim->>'email'='portal-invite-8502@example.test';
 ASSERT api.claim_portal_reminders(20)='[]'::jsonb,'réservation concurrente répétée';
 ASSERT api.start_portal_reminder((v_claim->>'id')::uuid,(v_claim->>'claim')::uuid),'début de livraison refusé';
 ASSERT NOT api.start_portal_reminder((v_claim->>'id')::uuid,(v_claim->>'claim')::uuid),'livraison répétée autorisée';
 UPDATE public.portal_invitation SET reminder_claimed_at=now()-interval '20 minutes' WHERE actor_id=v_actor;
 ASSERT api.claim_portal_reminders(20)='[]'::jsonb,'acquittement perdu provoque une seconde livraison';
 PERFORM api.finish_portal_reminder((v_claim->>'id')::uuid,(v_claim->>'claim')::uuid,true);
 PERFORM api.record_portal_invitation('ORGRUN9999998501',v_actor,v_user,v_office);
 UPDATE public.portal_invitation SET reminder_due_at=now()-interval '1 day' WHERE actor_id=v_actor;
 ASSERT api.claim_portal_reminders(20)='[]'::jsonb,'seconde relance après renvoi manuel';
 UPDATE public.portal_invitation SET reminder_sent_at=NULL,reminder_attempted_at=NULL WHERE actor_id=v_actor;
 UPDATE auth.users SET last_sign_in_at=now() WHERE id=v_user;
 ASSERT api.claim_portal_reminders(20)='[]'::jsonb,'compte activé relancé';
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',v_office,'role','authenticated','app_metadata',jsonb_build_object('sandbox_discovery',true))::text,true);
 ASSERT api.get_portal_launch('ORGRUN9999998501')#>>'{stats,activated}'='1';
 INSERT INTO public.fiche_submission(object_id,actor_id,submitted_by,status,submitted_at,resolved_at) VALUES('HOTRUN9999998501',v_actor,v_user,'approved',now()-interval '2 days',now()-interval '1 day');
 ASSERT api.get_portal_launch('ORGRUN9999998501')#>>'{stats,submitted}'='1';
 ASSERT (api.get_portal_launch('ORGRUN9999998501')->>'averageReviewDays')::numeric=1;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',v_office,'role','authenticated')::text,true);
 v_denied:=false;BEGIN PERFORM api.get_portal_launch('ORGRUN9999998501');EXCEPTION WHEN insufficient_privilege THEN v_denied:=true;END;ASSERT v_denied,'console traverse le périmètre test';
END $test$;
ROLLBACK;
